import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Link } from 'react-router-dom';
import API from '../services/api';
import TiltCard from '../components/TiltCard';

const roleColors = { 'Admin': '#ef4444', 'Record Manager': '#f59e0b', 'Authorized User': '#10b981', 'Auditor': '#6366f1' };

export default function Dashboard() {
  const { user } = useAuth();
  const [stats, setStats] = useState({ docs: 0, categories: 0, users: 0 });
  const [recentDocs, setRecentDocs] = useState([]);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const [docsRes, catRes] = await Promise.all([API.get('/documents?limit=5'), API.get('/categories')]);
        const s = { docs: docsRes.data.total || 0, categories: catRes.data.length || 0, users: 0 };
        if (user.role === 'Admin') {
          const usersRes = await API.get('/auth/users');
          s.users = usersRes.data.length;
        }
        setStats(s);
        setRecentDocs(docsRes.data.docs || []);
      } catch {}
    };
    fetchStats();
  }, [user.role]);

  const statCards = [
    { label: 'Total Documents', value: stats.docs, icon: '📄', color: '#4f46e5', bg: '#f0f0ff', link: '/documents' },
    { label: 'Categories', value: stats.categories, icon: '🗂', color: '#0891b2', bg: '#ecfeff', link: '/documents' },
    ...(user.role === 'Admin' ? [{ label: 'Total Users', value: stats.users, icon: '👥', color: '#059669', bg: '#ecfdf5', link: '#' }] : []),
  ];

  const quickActions = [
    { label: 'Upload Document', icon: '⬆', link: '/upload', color: '#4f46e5', roles: ['Admin', 'Record Manager'] },
    { label: 'Browse Documents', icon: '📁', link: '/documents', color: '#0891b2', roles: ['Admin', 'Record Manager', 'Authorized User', 'Auditor'] },
    { label: 'View Reports', icon: '📊', link: '/reports', color: '#059669', roles: ['Admin', 'Auditor'] },
    { label: 'Audit Logs', icon: '🔍', link: '/audit', color: '#d97706', roles: ['Admin', 'Auditor'] },
  ].filter(a => a.roles.includes(user.role));

  const permissions = [
    { label: 'Upload Documents', allowed: ['Admin', 'Record Manager'] },
    { label: 'Delete Documents', allowed: ['Admin', 'Record Manager'] },
    { label: 'Manage Categories', allowed: ['Admin', 'Record Manager'] },
    { label: 'View Audit Logs', allowed: ['Admin', 'Auditor'] },
    { label: 'Generate Reports', allowed: ['Admin', 'Auditor'] },
    { label: 'Manage Users', allowed: ['Admin'] },
    { label: 'Download Documents', allowed: ['Admin', 'Record Manager', 'Authorized User', 'Auditor'] },
    { label: 'Version Control', allowed: ['Admin', 'Record Manager'] },
  ];

  return (
    <div style={styles.page}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.greeting}>Good day, {user.name} 👋</h1>
          <p style={styles.subGreeting}>Here's what's happening in your system today.</p>
        </div>
        <div style={{ ...styles.rolePill, background: roleColors[user.role] || '#6366f1' }}>{user.role}</div>
      </div>

      {/* Stat Cards */}
      <div style={styles.statsGrid}>
        {statCards.map(card => (
          <Link to={card.link} key={card.label} style={{ textDecoration: 'none' }}>
            <TiltCard style={styles.statCard}>
              <div style={{ ...styles.statIcon, background: card.bg, color: card.color }}>{card.icon}</div>
              <div>
                <p style={styles.statValue}>{card.value}</p>
                <p style={styles.statLabel}>{card.label}</p>
              </div>
              <div style={{ ...styles.statBar, background: card.bg }}>
                <div style={{ ...styles.statBarFill, background: card.color, width: `${Math.min(card.value * 10, 100)}%` }} />
              </div>
            </TiltCard>
          </Link>
        ))}
      </div>

      <div style={styles.grid2}>
        {/* Quick Actions */}
        <TiltCard style={styles.section}>
          <h2 style={styles.sectionTitle}>Quick Actions</h2>
          <div style={styles.actionsGrid}>
            {quickActions.map(a => (
              <Link to={a.link} key={a.label} style={{ textDecoration: 'none' }}>
                <TiltCard style={styles.actionCard}>
                  <div style={{ ...styles.actionIcon, background: a.color }}>{a.icon}</div>
                  <span style={styles.actionLabel}>{a.label}</span>
                  <span style={styles.actionArrow}>→</span>
                </TiltCard>
              </Link>
            ))}
          </div>
        </TiltCard>

        {/* Recent Documents */}
        <TiltCard style={styles.section}>
          <div style={styles.sectionHeader}>
            <h2 style={styles.sectionTitle}>Recent Documents</h2>
            <Link to="/documents" style={styles.viewAll}>View all →</Link>
          </div>
          {recentDocs.length === 0 ? (
            <div style={styles.empty}>
              <span style={{ fontSize: '32px' }}>📭</span>
              <p>No documents yet</p>
            </div>
          ) : (
            <div style={styles.docList}>
              {recentDocs.map(doc => (
                <TiltCard key={doc._id} style={styles.docItem}>
                  <div style={styles.docIcon}>{doc.fileType === '.pdf' ? '📕' : doc.fileType === '.docx' ? '📘' : doc.fileType === '.xlsx' ? '📗' : '🖼'}</div>
                  <div style={styles.docInfo}>
                    <p style={styles.docTitle}>{doc.title}</p>
                    <p style={styles.docMeta}>{doc.department} • v{doc.currentVersion} • {new Date(doc.createdAt).toLocaleDateString()}</p>
                  </div>
                  <span style={styles.docBadge}>{doc.fileType?.replace('.', '').toUpperCase()}</span>
                </TiltCard>
              ))}
            </div>
          )}
        </TiltCard>
      </div>

      {/* Permissions */}
      <TiltCard style={styles.section}>
        <h2 style={styles.sectionTitle}>Your Permissions</h2>
        <div style={styles.permGrid}>
          {permissions.map(p => (
            <TiltCard key={p.label} style={{ ...styles.permItem, background: p.allowed.includes(user.role) ? '#f0fdf4' : '#fef2f2', border: `1px solid ${p.allowed.includes(user.role) ? '#bbf7d0' : '#fecaca'}` }}>
              <span>{p.allowed.includes(user.role) ? '✅' : '❌'}</span>
              <span style={{ fontSize: '13px', color: p.allowed.includes(user.role) ? '#166534' : '#991b1b' }}>{p.label}</span>
            </TiltCard>
          ))}
        </div>
      </TiltCard>
    </div>
  );
}

